// ============================================
// src/components/dashboard/DashboardHeader.jsx
// ============================================

import React from 'react';
import { Avatar, AvatarFallback } from '../ui/avatar';
import { Button } from '../ui/button';
import { LogOut } from 'lucide-react';
import { useAuth } from '../../contexts/AuthContext';

export const DashboardHeader = () => {
  const { user, logout } = useAuth();

  return (
    <header className="bg-white shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center py-4">
          <div className="flex items-center space-x-4">
            <img 
              src="https://customer-assets.emergentagent.com/job_cbf5d180-7dc8-49ac-bba7-d2fbaff8451a/artifacts/gmhdedz7_464681137_861366946106337_8408541761944089839_n.jpg"
              alt="EUREKA Logo"
              className="h-10 w-10 rounded-full"
            />
            <div>
              <h1 className="text-xl font-bold text-gray-900">EUREKA CRM</h1>
              <p className="text-sm text-gray-600">Sistema de Gestión Ambiental</p>
            </div>
          </div>
          
          <div className="flex items-center space-x-4">
            <Avatar>
              <AvatarFallback>
                {user?.full_name?.split(' ').map(n => n[0]).join('')}
              </AvatarFallback>
            </Avatar>
            <div className="text-right">
              <p className="text-sm font-medium text-gray-900">{user?.full_name}</p>
              <p className="text-xs text-gray-500">{user?.role}</p>
            </div>
            <Button 
              onClick={logout} 
              variant="outline" 
              size="sm"
              className="text-red-600 border-red-600 hover:bg-red-50"
            >
              <LogOut className="w-4 h-4 mr-2" />
              Salir
            </Button>
          </div>
        </div>
      </div>
    </header>
  );
};
